const categories = [
  { name: 'Artificial Intelligence', query: 'AI model release GPT Claude Gemini Grok LLM benchmark 2026 when:1d' },
  { name: 'AI Agents & Tools', query: 'AI agent automation workflow tool OpenAI Anthropic Google developer 2026 when:1d' },
  { name: 'Software Development', query: 'programming language framework React Node Python JavaScript TypeScript Rust 2026 when:2d' },
  { name: 'Developer Tools', query: 'GitHub VS Code IDE DevOps Docker Kubernetes CI/CD developer productivity 2026 when:2d' },
  { name: 'Cybersecurity', query: 'cybersecurity data breach hack vulnerability ransomware zero-day exploit 2026 when:1d' },
  { name: 'Tech Industry', query: 'tech startup acquisition IPO funding product launch Silicon Valley big tech 2026 when:2d' },
  { name: 'Cloud & Infrastructure', query: 'cloud computing AWS Azure Google Cloud serverless edge computing infrastructure 2026 when:2d' },
];
const pick = categories[Math.floor(Math.random() * categories.length)];
const q = encodeURIComponent(pick.query);
const feedUrl = 'https://news.google.com/rss/search?q=' + q + '&hl=en-US&gl=US&ceid=US:en';
return [{ json: { category: pick.name, feedUrl } }];

const items = $input.all();
if (!items.length) { return []; }
const category = $('Pick Trending Topic Feed').first().json.category;
const pool = items.slice(0, 6);
const chosen = pool[Math.floor(Math.random() * pool.length)].json;
const topic = String(chosen.title || '').replace(/\s+-\s+[^-]+$/, '').trim();
return [{ json: {
  category,
  topic,
  sourceUrl: chosen.link || chosen.guid || '',
  snippet: String(chosen.contentSnippet || chosen.content || '').slice(0, 400),
} }];

