const item = $input.first().json;
function tryParse(v) {
  if (v == null) return null;
  if (typeof v === 'object') return v;
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch (e) {
      const m = v.match(/\{[\s\S]*\}/);
      if (m) { try { return JSON.parse(m[0]); } catch (_) {} }
    }
  }
  return null;
}
let data = null;
if (Array.isArray(item.output)) {
  for (const o of item.output) {
    const contents = Array.isArray(o.content) ? o.content : [];
    for (const c of contents) {
      data = data || tryParse(c.text) || tryParse(c.output_text);
    }
  }
}
data = data || tryParse(item.content) || tryParse(item.text) || tryParse(item.output_text) || tryParse(item.message && item.message.content);
if (!data) { throw new Error('No JSON found in model output'); }
const meta = $('Select Top Headline').first().json;
data.category = data.category || meta.category;
data.sourceUrl = meta.sourceUrl || '';
data.topic = meta.topic || '';
if (Array.isArray(data.metaKeywords)) data.metaKeywords = data.metaKeywords.join(', ');
if (Array.isArray(data.tags) === false && typeof data.tags === 'string') data.tags = data.tags.split(',').map(t => t.trim()).filter(Boolean);
if (!data.imagePrompt) data.imagePrompt = 'Editorial photograph representing ' + (data.title || meta.topic);
if (!data.imageSearchQuery) data.imageSearchQuery = (data.category || '') + ' ' + (data.title || '').slice(0, 40);
return [{ json: data }];

const PEXELS_API_KEY = 'YOUR_PEXELS_API_KEY';
const data = $input.first().json;
const imageSearchQuery = (data.imageSearchQuery || data.title || data.category || 'technology').slice(0, 80);
const headline = (data.title || imageSearchQuery).slice(0, 80);
let inlineImage1 = null;
let inlineImage2 = null;
try {
  const wikiQuery = encodeURIComponent(headline);
  const wikiUrl = 'https://en.wikipedia.org/w/api.php?action=query&generator=search&gsrsearch=' + wikiQuery + '&gsrlimit=8&prop=pageimages&piprop=thumbnail|original&pithumbsize=1200&pilimit=8&format=json&origin=*';
  const wikiResp = await fetch(wikiUrl, { headers: { 'User-Agent': 'TrendwireBot/1.0' } });
  if (wikiResp.ok) {
    const wikiData = await wikiResp.json();
    const pages = Object.values(wikiData?.query?.pages || {});
    for (const page of pages) {
      const src = page?.original?.source || page?.thumbnail?.source;
      if (src && !src.toLowerCase().endsWith('.svg')) {
        inlineImage1 = { url: src, alt: page.title || imageSearchQuery, caption: 'Related image', source: 'Wikimedia Commons' };
        break;
      }
    }
  }
} catch (e) {}
if (PEXELS_API_KEY && PEXELS_API_KEY !== 'YOUR_PEXELS_API_KEY') {
  try {
    const pexelsQuery = encodeURIComponent(imageSearchQuery);
    const pexelsUrl = 'https://api.pexels.com/v1/search?query=' + pexelsQuery + '&per_page=3&orientation=landscape&size=large';
    const pexelsResp = await fetch(pexelsUrl, { headers: { 'Authorization': PEXELS_API_KEY } });
    if (pexelsResp.ok) {
      const pexelsData = await pexelsResp.json();
      const photos = pexelsData?.photos || [];
      if (photos.length > 0) {
        const photo = photos[0];
        const imgUrl = photo?.src?.large2x || photo?.src?.large || photo?.src?.medium;
        if (imgUrl) { inlineImage2 = { url: imgUrl, alt: photo.alt || imageSearchQuery, caption: 'Photo by ' + (photo.photographer || 'Pexels'), source: 'Pexels' }; }
      }
    }
  } catch (e) {}
}
return [{ json: { ...data, inlineImage1, inlineImage2 } }];

const data = $input.first().json;
let content = data.content || '';
function buildFigure(img) {
  if (!img || !img.url) return null;
  const alt = (img.alt || '').replace(/"/g, '&quot;');
  const caption = img.caption || '';
  const source = img.source || '';
  return '<figure class="inline-figure"><img src="' + img.url + '" alt="' + alt + '" loading="lazy" /><figcaption>' + caption + (source ? ' \u2014 via ' + source : '') + '</figcaption></figure>';
}
const fig1 = buildFigure(data.inlineImage1);
const fig2 = buildFigure(data.inlineImage2);
content = content.replace('<!--INLINE_IMAGE_1-->', fig1 || '');
content = content.replace('<!--INLINE_IMAGE_2-->', fig2 || '');
return [{ json: { ...data, content } }];

const input = $input.all();
const out = [];
for (let i = 0; i < input.length; i++) {
  const item = input[i];
  const binKey = item.binary ? (item.binary.data ? 'data' : Object.keys(item.binary)[0]) : null;
  const bin = binKey ? item.binary[binKey] : null;
  let mime = (bin && bin.mimeType) || 'image/png';
  let b64 = '';
  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, binKey || 'data');
    b64 = buf.toString('base64');
  } catch (e) {
    b64 = (bin && bin.data) ? bin.data : '';
  }
  out.push({ json: { imageBase64: b64, imageMime: mime } });
}
return out;
